values
  ('db417fc1-3482-50fa-87cd-a5077a36778a', null, (select id from public.skills where slug = 'read-g8-context-clues'), null, 'hard',
   $q$Yusuf makes a "tentative" suggestion. Which detail best shows what "tentative" means?$q$, $q$[{"text":"He spoke quietly \"as if he expected someone to reject the idea.\"","is_correct":true},{"text":"Ms. Varga \"wrote it on the board immediately.\"","is_correct":false,"misconception_token":"confuses-cause-effect"},{"text":"The river would run \"behind every scene.\"","is_correct":false,"misconception_token":"wrong-context-clue"},{"text":"Yusuf \"was new to the school.\"","is_correct":false,"misconception_token":"too-narrow"}]$q$::jsonb, $q$He spoke quietly "as if he expected someone to reject the idea."$q$, $q$Speaking quietly, looking at the floor, and expecting rejection show that a tentative suggestion is made in an unsure, hesitant way. Ms. Varga's quick response shows the idea was good, which tells us nothing about how Yusuf offered it.$q$, 'draft', '337b6a72-8c9c-5cc9-bd7e-7d39ff42813c')
