values
  ('d8f8f8da-a103-5ea5-b12b-f70df356a7a5', null, (select id from public.skills where slug = 'read-g8-figurative-language'), null, 'easy',
   $q$Some people call puns "cheap tricks," while others call them "tiny puzzles." How do these labels differ?$q$, $q$[{"text":"Both labels mean that puns are too hard for most readers.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"\"Cheap tricks\" sounds admiring; \"tiny puzzles\" sounds dismissive.","is_correct":false,"misconception_token":"reversed-connotation"},{"text":"Both labels are equally positive about puns and wordplay.","is_correct":false,"misconception_token":"misses-connotation"},{"text":"\"Cheap tricks\" sounds dismissive; \"tiny puzzles\" sounds admiring.","is_correct":true}]$q$::jsonb, $q$"Cheap tricks" sounds dismissive; "tiny puzzles" sounds admiring.$q$, $q$"Cheap" suggests something low in value, while "puzzles that reward careful attention" suggests something clever. The passage links the first label to people who "groan" and the second to people who "admire" puns.$q$, 'draft', 'b50ed876-622f-562a-abf8-d73bb0d6af55')
