  ('46db5751-7aa4-5408-832f-82346db0baeb', null, (select id from public.skills where slug = 'read-g8-figurative-language'), null, 'hard',
   $q$Hana describes the news about her monarch as "a postcard from a butterfly." What does she mean?$q$, $q$[{"text":"The butterfly flew back to her backyard to visit her again.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"The report felt like a message from far away saying it arrived.","is_correct":true},{"text":"The researchers mailed her a postcard with a butterfly picture.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"The butterfly was found carrying a card with her address on it.","is_correct":false,"misconception_token":"literal-reading"}]$q$::jsonb, $q$The report felt like a message from far away saying it arrived.$q$, $q$A postcard is a short note from someone on a trip, and the report told Hana that her butterfly had reached Mexico. The passage says only that researchers "reported" the news, so a real mailed postcard is not supported.$q$, 'draft', '89b4504f-6945-5d63-a6e0-b236c3d2ed1f')
