values
  ('52de2e37-6923-5886-a62a-938164216be9', null, (select id from public.skills where slug = 'read-g8-literary-structure-pov'), null, 'hard',
   $q$The visitors in the last stanza see only the finished garden. How does the poem's structure make the reader's understanding different from theirs?$q$, $q$[{"text":"The reader follows the garden from gravel to harvest, so the reader already knows the story the visitors are about to hear.","is_correct":true},{"text":"The reader learns the story from the visitors, who explain how Mrs. Ito began the garden years ago.","is_correct":false,"misconception_token":"confuses-speaker-character"},{"text":"The reader sees only the final stanza, so the reader knows less about the garden's history than the visitors do.","is_correct":false,"misconception_token":"reverses-pov"},{"text":"The reader and the visitors know the same things, since both arrive in the garden at the same time.","is_correct":false,"misconception_token":"misses-pov-difference"}]$q$::jsonb, $q$The reader follows the garden from gravel to harvest, so the reader already knows the story the visitors are about to hear.$q$, $q$Because the stanzas move in order from the empty lot to July, the reader knows the history before the children tell it to the visitors. The visitors ask questions; it is the children, not the visitors, who tell the story.$q$, 'draft', '8f1dbff1-9f04-534f-a72c-c1ab1455c97d')
