-- Passage rg8-story-details-inference-p01
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('35357fc7-92f2-58cf-871e-db790e0345a0', 'rg8-story-details-inference-p01', (select id from public.skills where slug = 'read-g8-story-details-inference'), null,
        '6-8', $q$The Seed Library$q$, $q$Priya had volunteered at the Linden Street Library every Saturday since September, but the seed library was her favorite job. It was an old card catalog with fifty small drawers, and each drawer held paper envelopes of seeds that neighbors could borrow for free. The only rule was printed on a sign above the cabinet: grow something, then bring back seeds for the next person.

Most people forgot the second half of the rule. By March, the tomato drawer was nearly empty, and the drawer for pole beans held a single crumpled envelope.

That morning, a tall man in a gardening hat set a shoebox on the counter. "Mr. Okafor," he said, tapping his chest as if Priya might not remember him. She did. Last spring he had taken the last packet of purple beans and asked her three questions about how deep to plant them.

Inside the shoebox were twenty envelopes, each labeled in careful block letters: PURPLE POLE BEANS. SAVED FROM ROW TWO. PLANT AFTER LAST FROST. One envelope also held a folded index card with a pencil sketch of a fence made from sticks and string.

"The rabbits found my first row," he said. "So I built that. Tell the next person."

Priya filled the bean drawer until it would barely close. Then she taped the sketch to the front of it, right below the label.$q$, 'draft')
