-- Passage rg8-story-details-inference-p02
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('07fb6fed-7705-5e89-8bcd-aa3f85115900', 'rg8-story-details-inference-p02', (select id from public.skills where slug = 'read-g8-story-details-inference'), null,
        '6-8', $q$Before the Sun$q$, $q$My uncle's alarm is a quiet song.
He silences it on the first note,
as if the dark were a sleeping baby.
I hear the floor creak twice, then nothing.

By the time I find my shoes,
the kitchen light is already off.
On the counter sits a paper bag,
warm on the bottom, folded twice.
Inside are two rolls, still soft,
and a note in flour-dusted pencil.
One for you. One for the bus driver.

All week I give the second roll away.
Ms. Delgado says thank you every time,
and every time she asks about him.
I tell her what I know.
He leaves before the sun.
He comes home smelling of cinnamon.
He falls asleep in the green chair
with the newspaper open on his chest.

On Saturday I set my own alarm.
I silence it on the first note.
I walk with him through the blue streets
to the shop with the fogged windows,
where he ties an apron around me twice
and shows me how the dough
pushes back when it is ready.$q$, 'draft')
