-- Passage rg8-story-details-inference-p05
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('7bab589a-3220-5236-a07d-68c18cd1ae9c', 'rg8-story-details-inference-p05', (select id from public.skills where slug = 'read-g8-story-details-inference'), null,
        '6-8', $q$Last One on the Field$q$, $q$The bleachers empty row by row.
The scoreboard keeps its numbers lit
a little longer than it should,
as if it wants me to read them twice.
Home, two. Visitors, three. We were home.
I read them twice.

Coach said the save in the second half
was the best she had seen all year.
She did not mention the first goal,
the one that rolled between my gloves
like water through a fence.
She did not have to.

My little brother waits by the gate,
kicking a pinecone back and forth.
He asks if I can show him how
to dive without landing on his elbow.
I almost say tomorrow.

Instead I drop my bag on the grass.
I set two water bottles for posts
and crouch between them, knees bent,
the way somebody taught me once.
He shoots. I fall the right way.
He shoots again, and laughs, and shoots,
until the scoreboard lights click off
and neither of us is counting.$q$, 'draft')
on conflict (id) do update set title = excluded.title, body = excluded.body
where public.passages.status = 'draft';
