-- Passage rg8-story-details-inference-p07
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('a638043c-0541-580c-8b26-1f826239decc', 'rg8-story-details-inference-p07', (select id from public.skills where slug = 'read-g8-story-details-inference'), null,
        '6-8', $q$The Count$q$, $q$Every December, the town's nature club spent one Saturday counting every bird it could find. This year, Jalen was assigned to walk the creek trail with Mrs. Avakian, who had done the count for forty years.

He expected her to bring binoculars. Instead she brought a folding stool, a thermos, and a small notebook with large, square pages.

At the first bend in the trail, she unfolded the stool and sat down. "Now we wait," she said, and closed her eyes.

Jalen shifted from one foot to the other. He could see nothing but bare branches and gray water. After a minute, Mrs. Avakian lifted one finger. "Two chickadees. One nuthatch, upside down on the sycamore, probably." She tapped the notebook. "Write those."

Jalen squinted at the sycamore. It took him a long moment to find the small gray bird creeping headfirst down the bark.

They continued like that for two hours. She listened, and he looked. Sometimes he spotted a bird before she named it, and she would nod and say, "Good. Write it." Twice she named a bird he never found at all, and she told him to write those too, with a small star beside them.

On the walk back, she handed him the thermos to carry. "My eyes quit on me a few years ago," she said, as if she were reporting the weather. "Next year, you bring the binoculars."$q$, 'draft')
